'use server';

import { createSupabaseAdminClient, createSupabaseServerClient } from "@/lib/supabase/server";
import { revalidatePath } from "next/cache";
import { format, startOfMonth, endOfMonth, subDays, startOfDay, endOfDay } from 'date-fns';

/**
 * ユーザーの出退勤を強制的に切り替える
 */
export async function forceToggleAttendance(userId: string) {
    const supabase = await createSupabaseAdminClient();

    try {
        const { data: attendanceUser, error: attUserError } = await supabase
            .schema('attendance')
            .from('users')
            .select('supabase_auth_user_id, card_id')
            .eq('supabase_auth_user_id', userId)
            .single();

        if (attUserError || !attendanceUser) {
            return { success: false, message: '勤怠ユーザーが見つかりません。' };
        }

        const { data: lastAttendance, error: lastAttendanceError } = await supabase
            .schema('attendance')
            .from('attendances')
            .select('type')
            .eq('user_id', attendanceUser.supabase_auth_user_id)
            .order('timestamp', { ascending: false })
            .limit(1)
            .maybeSingle();

        if (lastAttendanceError && lastAttendanceError.code !== 'PGRST116') {
            return { success: false, message: lastAttendanceError.message };
        }

        const newType = lastAttendance?.type === 'in' ? 'out' : 'in';

        const { error: insertError } = await supabase
            .schema('attendance')
            .from('attendances')
            .insert({ 
                user_id: attendanceUser.supabase_auth_user_id, 
                type: newType, 
                card_id: attendanceUser.card_id 
            });

        if (insertError) {
            return { success: false, message: insertError.message };
        }

        revalidatePath('/admin');
        revalidatePath('/dashboard/teams', 'page');
        revalidatePath('/dashboard/layout');

        return { 
            success: true, 
            message: `ユーザーを強制的に${newType === 'in' ? '出勤' : '退勤'}させました。` 
        };
    } catch (error) {
        console.error('Error in forceToggleAttendance:', error);
        return { success: false, message: '予期しないエラーが発生しました。' };
    }
}

/**
 * 日次出勤ログを全件取得
 */
export async function getAllDailyLogoutLogs() {
    const supabase = await createSupabaseAdminClient();
    return supabase
        .schema('attendance')
        .from('daily_logout_logs')
        .select('*')
        .order('timestamp', { ascending: false });
}

/**
 * 月次出席サマリーを取得
 */
export async function getMonthlyAttendanceSummary(month: Date) {
    const supabase = await createSupabaseAdminClient();
    const start = format(startOfMonth(month), 'yyyy-MM-dd');
    const end = format(endOfMonth(month), 'yyyy-MM-dd');

    const { data, error } = await (supabase as any).rpc('get_monthly_attendance_summary', { 
        start_date: start, 
        end_date: end 
    });

    if (error) {
        console.error('Error fetching monthly attendance summary:', error);
        return {};
    }

    type DailySummary = {
        total: number;
        byTeam: Record<string, { name: string; total: number; byGeneration: Record<number, number> }>;
    };

    const summary: Record<string, DailySummary> = {};

    if (data) {
        for (const record of (data as any[])) {
            const { date, team_id, team_name, generation, count } = record;
            if (!date || !team_id || !team_name || count === null) continue;

            const dateKey = format(new Date(date), 'yyyy-MM-dd');

            if (!summary[dateKey]) {
                summary[dateKey] = { total: 0, byTeam: {} };
            }

            if (!summary[dateKey].byTeam[team_id]) {
                summary[dateKey].byTeam[team_id] = { name: team_name, total: 0, byGeneration: {} };
            }

            summary[dateKey].total += count;
            summary[dateKey].byTeam[team_id].total += count;
            summary[dateKey].byTeam[team_id].byGeneration[generation] = count;
        }
    }

    return summary;
}

/**
 * 日別出勤数を取得
 */
export async function getDailyAttendanceCounts(month: Date) {
    const supabase = await createSupabaseAdminClient();
    const start = format(startOfMonth(month), 'yyyy-MM-dd');
    const end = format(endOfMonth(month), 'yyyy-MM-dd');

    const { data, error } = await (supabase as any).rpc('get_monthly_attendance_summary', { 
        start_date: start, 
        end_date: end 
    });

    if (error) {
        console.error('Failed to fetch monthly attendance summary:', error);
        throw new Error('月次出席サマリーの取得に失敗しました');
    }

    const dailyCounts = new Map<string, number>();

    if (data) {
        for (const record of (data as any[])) {
            const dateKey = format(new Date(record.date), 'yyyy-MM-dd');
            dailyCounts.set(dateKey, (dailyCounts.get(dateKey) || 0) + (record.count || 0));
        }
    }

    return dailyCounts;
}

/**
 * 特定日の出勤詳細を取得
 */
export async function getDailyAttendanceDetails(date: Date) {
    const supabase = await createSupabaseAdminClient();
    const targetDate = format(date, 'yyyy-MM-dd');

    const { data, error } = await (supabase as any).rpc('get_monthly_attendance_summary', { 
        start_date: targetDate, 
        end_date: targetDate 
    });

    if (error) {
        console.error('Failed to fetch daily attendance details:', error);
        throw new Error('日次出席詳細の取得に失敗しました');
    }

    type DailyDetail = {
        total: number;
        byTeam: Record<string, { name: string; total: number; byGeneration: Record<number, number> }>;
    };

    const detail: DailyDetail = { total: 0, byTeam: {} };

    if (data) {
        for (const record of (data as any[])) {
            const { team_id, team_name, generation, count } = record;
            if (!team_id || !team_name || count === null) continue;

            if (!detail.byTeam[team_id]) {
                detail.byTeam[team_id] = { name: team_name, total: 0, byGeneration: {} };
            }

            detail.total += count;
            detail.byTeam[team_id].total += count;
            detail.byTeam[team_id].byGeneration[generation] = count;
        }
    }

    return detail;
}

/**
 * 全体統計を取得
 */
export async function getOverallStats(days: number = 30) {
    const supabase = await createSupabaseAdminClient();
    const today = new Date();
    const startDate = format(subDays(today, days - 1), 'yyyy-MM-dd');
    const endDate = format(today, 'yyyy-MM-dd');

    try {
        // 総メンバー数
        const { count: totalMembers } = await supabase
            .schema('member')
            .from('members')
            .select('*', { count: 'exact', head: true })
            .is('deleted_at', null);

        // 今日の出席者数
        const { data: attendanceUsers } = await supabase
            .schema('attendance')
            .from('users')
            .select('supabase_auth_user_id');

        const attendanceUserIds = attendanceUsers?.map(u => u.supabase_auth_user_id) || [];

        const { data: todayAttendanceData } = await supabase
            .schema('attendance')
            .from('attendances')
            .select('user_id', { count: 'exact' })
            .eq('type', 'in')
            .gte('timestamp', startOfDay(today).toISOString())
            .lte('timestamp', endOfDay(today).toISOString())
            .in('user_id', attendanceUserIds);

        const uniqueTodayAttendees = todayAttendanceData 
            ? new Set(todayAttendanceData.map(d => d.user_id)).size 
            : 0;

        // 過去N日間の活動日数
        const { data: activityDays } = await supabase
            .schema('attendance')
            .from('attendances')
            .select('date', { count: 'exact' })
            .gte('date', startDate)
            .lte('date', endDate);

        const uniqueActivityDays = activityDays 
            ? new Set(activityDays.map(d => d.date)).size 
            : 0;

        // 過去N日間の合計活動時間
        const { data: activityHours } = await supabase
            .schema('attendance')
            .from('attendances')
            .select('user_id, type, timestamp')
            .gte('timestamp', subDays(today, days - 1).toISOString())
            .order('user_id')
            .order('timestamp');

        let totalHours = 0;
        if (activityHours) {
            const userSessions = new Map<string, Date[]>();
            activityHours.forEach((record: any) => {
                if (!userSessions.has(record.user_id)) {
                    userSessions.set(record.user_id, []);
                }
                userSessions.get(record.user_id)!.push(new Date(record.timestamp));
            });

            userSessions.forEach(timestamps => {
                for (let i = 0; i < timestamps.length - 1; i += 2) {
                    const diff = timestamps[i + 1].getTime() - timestamps[i].getTime();
                    totalHours += diff / (1000 * 60 * 60);
                }
            });
        }

        return {
            totalMembers: totalMembers || 0,
            todayAttendees: uniqueTodayAttendees,
            activityDays: uniqueActivityDays,
            totalHours: Math.round(totalHours * 10) / 10,
        };
    } catch (error) {
        console.error('Error in getOverallStats:', error);
        return {
            totalMembers: 0,
            todayAttendees: 0,
            activityDays: 0,
            totalHours: 0,
        };
    }
}

-- Create the attendance schema
create schema if not exists attendance;

-- Grant usage to necessary roles
grant usage on schema attendance to postgres, anon, authenticated, service_role;

-- Set default grants for new tables in the attendance schema
alter default privileges in schema attendance grant all on tables to postgres, anon, authenticated, service_role;
alter default privileges in schema attendance grant all on functions to postgres, anon, authenticated, service_role;
alter default privileges in schema attendance grant all on sequences to postgres, anon, authenticated, service_role;

--
-- attendance.users TABLE
--
create table attendance.users (
    supabase_auth_user_id uuid not null primary key references member.members(supabase_auth_user_id) on delete cascade,
    card_id character varying not null unique,
    created_at timestamp with time zone not null default now(),
    updated_at timestamp with time zone not null default now()
);
alter table attendance.users enable row level security;

create policy "Allow all access to service_role" on attendance.users for all to service_role using (true) with check (true);
create policy "Allow read access to authenticated users" on attendance.users for select to authenticated using (true);


--
-- attendance.attendances TABLE
--
create table attendance.attendances (
    id uuid not null default gen_random_uuid() primary key,
    user_id uuid not null references attendance.users (supabase_auth_user_id) on delete cascade,
    card_id character varying not null,
    "type" character varying not null,
    "timestamp" timestamp with time zone not null default now(),
    date date not null default (now() at time zone 'utc'::text),
    created_at timestamp with time zone not null default now()
);
alter table attendance.attendances enable row level security;
create index idx_attendances_date_user on attendance.attendances using btree (date, user_id);
create index idx_attendances_user_timestamp on attendance.attendances using btree (user_id, "timestamp");

create policy "Allow all access to service_role" on attendance.attendances for all to service_role using (true) with check (true);
create policy "Allow read access to user for their own records" on attendance.attendances for select to authenticated using ((select auth.uid()) = user_id);


--
-- attendance.temp_registrations TABLE
--
create table attendance.temp_registrations (
    id uuid not null default gen_random_uuid() primary key,
    card_id character varying not null,
    qr_token character varying not null,
    expires_at timestamp with time zone not null,
    is_used boolean not null default false,
    accessed_at timestamp with time zone,
    created_at timestamp with time zone not null default now()
);
alter table attendance.temp_registrations enable row level security;

create unique index temp_registrations_card_id_is_used_expires_at_idx on attendance.temp_registrations (card_id, is_used, expires_at);
create unique index temp_registrations_qr_token_key on attendance.temp_registrations using btree (qr_token);
create index idx_temp_registrations_expires on attendance.temp_registrations using btree (expires_at);

create policy "Allow all access to service_role" on attendance.temp_registrations for all to service_role using (true) with check (true);
create policy "Allow read access for all users" on attendance.temp_registrations for select using (true);


--
-- attendance.daily_logout_logs TABLE
--
create table attendance.daily_logout_logs (
    id uuid not null default gen_random_uuid() primary key,
    executed_at timestamp with time zone not null default now(),
    affected_count integer not null,
    status character varying not null
);
alter table attendance.daily_logout_logs enable row level security;
create policy "Allow all access to service_role" on attendance.daily_logout_logs for all to service_role using (true) with check (true);


--
-- Realtime Publication Setup
--
-- temp_registrations テーブルをRealtimeで監視可能にする（QRコード読み取り検知用）
alter publication supabase_realtime add table attendance.temp_registrations;

