251	  const supabase = useMemo(() => createSupabaseBrowserClient(), []);
252	
253	  useEffect(() => {
254	    setKioskState('idle');
255	  }, []);
256	
257	  const resetToIdle = useCallback(() => {
258	    if (resetTimerRef.current) clearTimeout(resetTimerRef.current);
259	    if (processingTimerRef.current) clearTimeout(processingTimerRef.current);
260	    setKioskState('idle');
261	    setInputValue('');
262	    setMessage('');
263	    setSubMessage('');
264	    setQrToken(null);
265	    setAttendanceType(null);
